function validate(input) {
  const [{ OrdersDetails = [] }] = input;
  const seen = new Set();
  for (const [order, product, quantity] of OrdersDetails) {
    if (order === null || product === null) return 'Every row needs an order_id and a product_id.';
    const key = `${order}:${product}`;
    if (seen.has(key)) return `Order ${order} lists product ${product} twice.`;
    seen.add(key);
    if (quantity === null || quantity < 1) return 'Every quantity must be a positive integer.';
  }
  return null;
}

