function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const orders = size === 'small' ? pick(5) : 320;
  const products = size === 'small' ? 6 : 12;
  const top = size === 'small' ? 12 : 60;
  const OrdersDetails = [];
  for (let order = 1; order <= orders; order++) {
    const count = 1 + pick(size === 'small' ? 3 : 6);
    const chosen = new Set();
    while (chosen.size < count) chosen.add(1 + pick(products));
    // Small cases sometimes give every product the same quantity, so max equals average.
    const flat = size === 'small' && rand() < 0.25 ? 1 + pick(top) : null;
    for (const product of chosen) OrdersDetails.push([order, product, flat ?? 1 + pick(top)]);
  }
  // Shuffle so rows of an order are not adjacent.
  for (let i = OrdersDetails.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [OrdersDetails[i], OrdersDetails[j]] = [OrdersDetails[j], OrdersDetails[i]];
  }
  return [{ OrdersDetails }];
}
